tool_calls.name:
/bin/zsh -lc "cat > auth/auth.go.tmp <<'EOF'
package auth

type Session struct {
	Token string
}

func VerifyToken(token string) bool {
	return token "'!= ""
}
EOF
sync -f auth/auth.go.tmp && mv auth/auth.go.tmp auth/auth.go
rm auth/token.go
cat > cmd/main.go.tmp <<'"'EOF'
package main

import (
	\"fmt\"
	\"example.com/test/auth\"
)

func CheckAuth(token string) bool {
	return auth.VerifyToken(token)
}

func main() {
	fmt.Println(CheckAuth(\"secret\"))
}
EOF
sync -f cmd/main.go.tmp && mv cmd/main.go.tmp cmd/main.go
rg -n --hidden --glob '"'!go.mod'"' --glob '"'!go.sum'"' '\\bValidateToken\\b|\\bVerifyToken\\b' ."

